import {required,faultModes,snapshot} from './workshop-model.mjs';
import {newRepair,intervene,repairState,causes} from './workshop-repair-model.mjs';
export const repairExamKey='mecanica.workshop.repairExam.v1',repairExamArchiveKey='mecanica.workshop.repairExams.v1';
export function newRepairExam(random=Math.random){return {id:crypto.randomUUID(),started:new Date().toISOString(),finished:null,index:0,cases:Object.keys(required).map(kind=>({repair:newRepair({kind,fault:faultModes[Math.min(4,Math.floor(random()*5))]}),observations:[],submitted:false}))};}
export function examIntervene(c,id){if(c.submitted)return false;intervene(c.repair,id);c.observations=[];return true;}
export function examMeasure(c,id,time){if(c.submitted||!required[c.repair.kind].includes(id)||![.5,1.25].includes(time))return false;if(!c.observations.some(x=>x.id===id&&x.time===time))c.observations.push({id,time});return true;}
export function repairExamGrade(c){const r=c.repair,remaining=causes(r).filter(x=>!r.fixed.includes(x)),unnecessary=r.actions.filter(a=>!a.useful).length,evidence=required[r.kind].every(id=>[.5,1.25].every(time=>c.observations.some(x=>x.id===id&&x.time===time))),state=repairState(r),matches=Array.from({length:800},(_,i)=>i/100).every(time=>JSON.stringify(snapshot({...state,time}))===JSON.stringify(snapshot({...state,time},true)));return {remaining,unnecessary,evidence,verified:matches&&evidence,score:Math.max(0,100-40*remaining.length-15*unnecessary-(evidence?0:20))};}
export function submitRepairCase(e){if(e.finished)return false;const c=e.cases[e.index];if(c.submitted)return false;c.submitted=true;if(e.index===3)e.finished=new Date().toISOString();else e.index++;return true;}
export function validRepairExam(e){return Boolean(e&&typeof e.id==='string'&&Number.isInteger(e.index)&&e.index>=0&&e.index<4&&(!e.finished||Number.isFinite(Date.parse(e.finished)))&&Array.isArray(e.cases)&&e.cases.length===4&&e.cases.every((c,i)=>{const r=c?.repair;return r&&r.kind===Object.keys(required)[i]&&faultModes.includes(r.fault)&&Array.isArray(r.fixed)&&r.fixed.every(x=>causes(r).includes(x))&&Array.isArray(r.actions)&&r.actions.every(a=>a&&['primary','alternate'].includes(a.id)&&typeof a.useful==='boolean')&&Array.isArray(c.observations)&&c.observations.every(o=>o&&required[r.kind].includes(o.id)&&[.5,1.25].includes(o.time))&&typeof c.submitted==='boolean'&&(!e.finished||c.submitted); }));}
export function loadRepairExams(storage){const rows=JSON.parse(storage.getItem(repairExamArchiveKey)||'[]');return Array.isArray(rows)?rows.filter(e=>validRepairExam(e)&&e.finished).filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i).slice(-25):[];}
export function saveRepairExam(storage,e){storage.setItem(repairExamKey,JSON.stringify(e));if(e.finished){const rows=loadRepairExams(storage);if(!rows.some(x=>x.id===e.id))storage.setItem(repairExamArchiveKey,JSON.stringify([...rows,e].slice(-25)));}}
export function repairExamEvidence(storage){return loadRepairExams(storage).flatMap(e=>e.cases.map(c=>({id:e.id+':'+c.repair.kind,kind:c.repair.kind,fault:c.repair.fault,finished:e.finished,...repairExamGrade(c)})));}
